{'content': '// Battery dimensions
batt_width = 36;
batt_height = 56;
batt_thickness = 13;

// Clearance for easy fit
clearance = 0.5;

// Slot dimensions
slot_w = batt_width + clearance * 2;
slot_t = batt_thickness + clearance * 2;
slot_h = 30; // Half-height to keep it compact and printable

// Wall thickness
wall = 2;

// Finger hole
finger_hole_r = 10;

// Number of batteries
num_batt = 4;

// Case dimensions
case_w = slot_w + 2 * wall;
case_l = (slot_t * num_batt) + (wall * (num_batt + 1));
case_h = slot_h + wall;

module battery_case() {
    difference() {
        // Main block
        cube([case_w, case_l, case_h]);

        // Battery slots
        for (i = [0 : num_batt - 1]) {
            translate([
                wall, 
                wall + i * (slot_t + wall), 
                wall
            ])
            cube([slot_w, slot_t, case_h + 1]);

            // Finger hole at the bottom
            translate([case_w/2, wall + i * (slot_t + wall) + slot_t/2, -1])
            cylinder(h = wall + 2, r = finger_hole_r, $fn=50);
        }

        // Side cutouts for easier gripping
        for (i = [0 : num_batt - 1]) {
             translate([-1, wall + i * (slot_t + wall) + slot_t/4, case_h - 10])
             cube([case_w + 2, slot_t/2, 11]);
        }
    }

    // Snap-fit tabs
    for (i = [0 : num_batt - 1]) {
        // Front and back snap tabs on the top edge
        translate([wall, wall + i * (slot_t + wall), case_h])
        rotate([0, 0, 0])
        snap_tab();

        translate([case_w - wall, wall + i * (slot_t + wall) + slot_t, case_h])
        rotate([0, 0, 180])
        snap_tab();
    }
}

module snap_tab() {
    // A small bump to provide retention
    translate([0, 0, -2])
    hull() {
        cube([slot_w, 0.5, 0.1]);
        translate([0, 0.8, 1])
        sphere(r=0.5, $fn=12);
        translate([slot_w, 0.8, 1])
        sphere(r=0.5, $fn=12);
    }
}

battery_case();
'}

{'content': '// Battery dimensions: 56 mm x 36 mm x 13 mm
// Arranged on smallest face (13x36), facing each other with largest face (56x36)
// This means the slot is ~36 wide and ~13 thick.

batt_w = 36;
batt_t = 13;
batt_h = 56;

// Clearances
clearance = 0.6;
wall = 2.0;

// Calculated slot dimensions
slot_w = batt_w + clearance;
slot_t = batt_t + clearance;
slot_h = 35; // Height of the case (shorter than battery for easy removal)

num_batt = 4;

// Case overall dimensions
case_w = slot_w + 2 * wall;
case_l = (num_batt * slot_t) + ((num_batt + 1) * wall);
case_h = slot_h + wall;

module battery_case() {
    difference() {
        // Main outer body
        cube([case_w, case_l, case_h]);

        // Cutouts for batteries
        for (i = [0 : num_batt - 1]) {
            y_pos = wall + i * (slot_t + wall);

            // The battery slot
            translate([wall, y_pos, wall])
                cube([slot_w, slot_t, case_h + 1]);

            // Finger hole in the bottom
            translate([case_w/2, y_pos + slot_t/2, -1])
                cylinder(h = wall + 2, d = 20, $fn=50);
        }

        // Side finger notches for grip
        for (i = [0 : num_batt - 1]) {
            y_pos = wall + i * (slot_t + wall);
            translate([-1, y_pos + slot_t/2, case_h])
                rotate([0, 90, 0])
                cylinder(h = case_w + 2, d = 15, $fn=50);
        }
    }

    // Snap-fit bumps (small ribs to hold the battery)
    // We place these on the side walls of each slot
    for (i = [0 : num_batt - 1]) {
        y_pos = wall + i * (slot_t + wall);

        // Snap bump left
        translate([wall, y_pos + slot_t/2, case_h - 5])
            sphere(d = 1.5, $fn=20);

        // Snap bump right
        translate([wall + slot_w, y_pos + slot_t/2, case_h - 5])
            sphere(d = 1.5, $fn=20);
    }
}

battery_case();
'}

{'content': '// Case for 4 Olympus BLS-5 batteries (56 x 36 x 13 mm)
// Linear 4x1 arrangement, upright on thin edge (13x36)

batt_w = 36;
batt_t = 13;
batt_h = 56;

// Tolerances and wall thickness
clearance = 0.8; // Generous clearance for 3D printing
wall = 2.4;     // Stronger walls

// Slot dimensions (internal)
slot_w = batt_w + clearance;
slot_t = batt_t + clearance;
slot_h = 35; // Depth of the slot (batteries stick out for removal)

num_batt = 4;

// Case overall dimensions
case_w = slot_w + 2 * wall;
case_l = (num_batt * slot_t) + ((num_batt + 1) * wall);
case_h = slot_h + wall; // Add floor thickness

module battery_case() {
    difference() {
        // Main outer body
        cube([case_w, case_l, case_h]);

        // Cutouts for batteries and features
        for (i = [0 : num_batt - 1]) {
            y_pos = wall + i * (slot_t + wall);

            // 1. The battery slot
            translate([wall, y_pos, wall])
                cube([slot_w, slot_t, slot_h + 10]);

            // 2. Finger hole in the bottom for pushing batteries up
            translate([case_w / 2, y_pos + slot_t / 2, -1])
                cylinder(h = wall + 2, d = 14, $fn = 50);

            // 3. Side cutouts for easier grasping (U-shape)
            // Cutout through the sides of the case
            translate([-1, y_pos + (slot_t/2) - 8, case_h - 10])
                cube([case_w + 2, 16, 12]);
        }
    }

    // Snap-fit bumps
    // These are small hemispherical bumps inside the slots to provide friction/click
    for (i = [0 : num_batt - 1]) {
        y_pos = wall + i * (slot_t + wall);

        // Front and back face bumps (on the large faces of the battery)
        // Adjusting positions to be inside the slot

        // Bump on one side wall of slot
        translate([wall + slot_w/2, y_pos + 0.3, case_h - 4])
            sphere(d = 1.6, $fn = 20);

        // Bump on opposing side wall of slot
        translate([wall + slot_w/2, y_pos + slot_t - 0.3, case_h - 4])
            sphere(d = 1.6, $fn = 20);
    }
}

// Render the case
battery_case();
